"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[55583],{55583:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/seven-years-of-night.png\\"\\n          title=\\"Seven Years of Night\\"\\n          author=\\"Jeong You-jeong\\"\\n          publisher=\\"Eunhaengnamu\\"\\n          publishedDate=\\"2016-05-30\\"\\n          isbn=\\"9788956604992\\"\\n          rating=4\\n          tags=\\"thriller\\"\\n        />\\n</center>\\n\\n## Review\\nReading <mark>Jeong You-jeong</mark>\'s works is suffocating.  \\nThe depiction of the characters\' situations and their emotions is so vivid that it\'s difficult to read.  \\nThe terrible mistake of one night by a character named ```Choi Hyeon-su``` becomes the seed of all tragedy.  \\n<br>\\nIt seems that characters with psychopathic tendencies appear every time in the author\'s works.  \\nIn this work as well, that character is indeed quite tenacious.  \\n<br>\\nThis work seems to be a story about two tragic versions of <mark>fatherly love</mark>.\\nA tragic fatherly love that plunged his son into hell through a momentary mistake but tries to save him by sacrificing himself at the last moment.  \\nThe other is a twisted and destructive fatherly love that regards his daughter as a possession and uses his dead daughter as a tool for his own revenge.\\nThe stark contrast between these two fathers seems to throw a heavy question: ```What is true love?```  "}')}}]);